import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Welcome to Ceph Days Silicon Valley 2025!","description":"","frontmatter":{"title":"Welcome to Ceph Days Silicon Valley 2025!","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-09T00:00:00.000Z","tags":["Ceph","Distributed Storage","Linux","Storage Technology","Data Center"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Welcome_to_Ceph_Days_Silicon_Valley_2025.md","filePath":"posts/2025/Welcome_to_Ceph_Days_Silicon_Valley_2025.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Welcome_to_Ceph_Days_Silicon_Valley_2025.md"};function r(n,e,h,s,p,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<p>会议纪要</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>Ceph社区日</p><h3 id="日期" tabindex="-1">日期 <a class="header-anchor" href="#日期" aria-label="Permalink to &quot;日期&quot;">​</a></h3><p>未知</p><h3 id="地点" tabindex="-1">地点 <a class="header-anchor" href="#地点" aria-label="Permalink to &quot;地点&quot;">​</a></h3><p>IBM存储研发总部</p><h3 id="主持人" tabindex="-1">主持人 <a class="header-anchor" href="#主持人" aria-label="Permalink to &quot;主持人&quot;">​</a></h3><p>Vu，IBM Fellow 兼 CTO for Storage，Ceph社区董事会代表</p><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>Vu首先欢迎与会者参加Ceph社区日，并介绍了会议地点的重要性。IBM存储的许多核心技术，包括磁带和硬盘的发明，都源自该地点。Vu强调了存储技术从传统的硬件驱动（如RPM）向平台化、基础设施化的转变，并指出当前行业趋势更关注于平台和数据中心的核心资产——数据。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph的愿景与目标</strong>:</p><ul><li>Vu提到Ceph社区的愿景是将Ceph打造成存储领域的“Linux”，即成为所有工作负载的默认存储操作系统。</li><li>强调了技术的可消费性（consumability），即不仅仅是技术性能的提升，还需要关注如何让用户更容易配置、部署和支持Ceph。</li></ul></li><li><p><strong>行业趋势与技术创新</strong>:</p><ul><li>Vu指出，当前行业分析师（如Gartner、IDC）不再仅仅关注存储硬件，而是更关注平台和基础设施的整体解决方案。</li><li>Ceph社区需要推动技术创新，确保Ceph成为数据中心的标准存储解决方案。</li></ul></li><li><p><strong>社区合作与协作</strong>:</p><ul><li>Vu鼓励社区成员之间的合作，确保Ceph能够在全球范围内被广泛采用。</li><li>强调了Ceph不仅仅是IBM的技术，而是整个存储行业的产物，源自该地区的创新。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>推动Ceph成为存储领域的标准</strong>: 社区需要继续推动Ceph的技术创新，并确保其易于使用和部署。</li><li><strong>加强社区合作</strong>: 鼓励社区成员之间的协作，确保Ceph在全球范围内的采用率提升。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>年度进展报告</strong>: 计划在明年的Ceph社区日上发布关于Ceph在操作系统环境中采用率的进展报告。</li><li><strong>技术讨论与演示</strong>: 接下来的议程将包括关于Ceph在销售和技术方面的详细讨论。</li></ul><h4 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h4><p>Ceph, distributed storage, Linux, platform, consumability, community collaboration, adoption, innovation, storage technology, data center, infrastructure, IBM</p>',19)])])}const _=a(i,[["render",r]]);export{d as __pageData,_ as default};
